# Run from the package root after 53, 55 and 58:  caffeinate -i Rscript data-raw/qa/59_decision_impact.R     (progress: data-raw/qa/out/59.log)   Saves data-raw/qa/out/decision_impact.rds
# Impact of the planned decisions (report only): (a) tornadoes with no usable end point placed at their start point; (b) widths of 0; (d) maps from the full TIGER/Line boundaries; (e) sizes with no alteration.
suppressMessages({library(sf); library(dplyr)}); sf_use_s2(FALSE); options(width = 220, tigris_use_cache = TRUE, timeout = 3600)
source("data-raw/qa/helpers.R"); source("data-raw/survey/pairing_functions.R"); lg <- function(...) { m <- paste0(format(Sys.time(), "%H:%M:%S "), ...); cat(m, "\n"); cat(m, "\n", file = qa_out("59.log"), append = TRUE) }
for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f); R <- list(); tt <- st_drop_geometry(tornado_tracks); yr <- as.integer(substr(tt$tornado_id, 1, 4)); era <- ifelse(yr < 2007, "1996-2006", "2007+"); vint <- ifelse(yr < 2010, 2000L, ifelse(yr < 2020, 2010L, 2020L))
Zfull <- function(v) { sfx <- substr(v, 3, 4); z <- tigris::zctas(year = v, progress_bar = FALSE); z <- z[, paste0("ZCTA5CE", sfx)]; names(z)[1] <- "ZCTA"; st_make_valid(st_transform(z, 5070)) }
# ---- (a) D1 -----------------------------------------------------------------------------------------------------------------------------------------------------------
pt <- which(tt$track_type != "line"); P5 <- st_transform(st_geometry(tornado_tracks)[pt], 5070); nz <- integer(length(pt)); first <- rep(NA_character_, length(pt))
for (v in c(2000, 2010, 2020)) { z <- Zfull(v); kk <- which(vint[pt] == v); h <- st_intersects(P5[kk], z); nz[kk] <- lengths(h); first[kk] <- vapply(h, function(x) if (length(x)) z$ZCTA[x[1]] else NA_character_, "") ; lg("start points of ", v, ": ", length(kk), "; in no ZCTA ", sum(lengths(h) == 0)) }
expo <- split(tornado_exposure$ZCTA, tornado_exposure$tornado_id); rows <- vapply(tt$tornado_id[pt], function(i) length(expo[[i]]), 1L); extra <- ifelse(is.na(first), rows, vapply(seq_along(pt), function(j) sum(expo[[tt$tornado_id[pt[j]]]] != first[j]), 1L))
R$d1_start <- data.frame(type = tt$track_type[pt], era = era[pt], in_no_zcta = nz == 0, in_one = nz == 1, in_more = nz > 1, published_rows = rows, extra_zctas = extra) %>% group_by(type, era) %>% summarise(tornadoes = n(), start_in_no_zcta = sum(in_no_zcta), start_in_more_than_one_zcta = sum(in_more), published_rows = sum(published_rows), zctas_beyond_the_start_zcta = sum(extra_zctas), share_with_extra = mean(extra_zctas > 0), mean_extra = mean(extra_zctas), max_extra = max(extra_zctas), .groups = "drop")
R$d1_totals <- c(point_tornadoes = length(pt), start_in_no_zcta = sum(nz == 0), published_rows_of_point_tornadoes = sum(rows), rows_after_D1_one_per_tornado_with_a_start_zcta = sum(nz >= 1), published_rows_total = nrow(tornado_exposure), rows_after_D1 = nrow(tornado_exposure) - sum(rows) + sum(nz >= 1))
R$d1_noz_point <- table(tt$track_type[!tt$tornado_id %in% tornado_exposure$tornado_id])
R$d1_start_none_and_published_rows <- sum(nz == 0 & rows > 0)
R$d1_by_rating <- table(ifelse(is.na(tt$magnitude[pt]), "unknown", paste0("EF", tt$magnitude[pt])), nz[nz == nz] == 0)
# README and table examples: are the example tornadoes line tracks?
ex_ids <- c(Joplin = "2011_1105221634-01", Moore = "2013_1305201356-01", Mayfield = "2021_2112102054-01", `Tuscaloosa-Birmingham` = "2011_1104271543-01", `St. Louis` = "2025_2505161339-01"); R$d1_example_types <- tt$track_type[match(ex_ids, tt$tornado_id)]; names(R$d1_example_types) <- names(ex_ids)
moore_zip <- tornado_exposure[tornado_exposure$ZCTA %in% c("73160", "73165", "73170") & tornado_exposure$year %in% 2010:2013 & tornado_exposure$magnitude %in% 4:5, ]; R$d1_readme_moore_types <- table(moore_zip$track_type); jop <- tornado_exposure[substr(tornado_exposure$ZCTA, 1, 3) == "648" & tornado_exposure$year == 2011 & tornado_exposure$magnitude %in% 5, ]; R$d1_readme_joplin_types <- table(jop$track_type)
# survey agreement tables: included tornadoes by track type and the agreement with SPC rows by type
inc <- survey_matches$tornado_id[survey_matches$status == "included"]; R$d1_included_by_type <- table(tt$track_type[match(inc, tt$tornado_id)]); R$d1_survey_rows_by_type <- table(survey_exposure$track_type)
J <- full_join(tornado_exposure[tornado_exposure$tornado_id %in% inc, c("tornado_id", "ZCTA", "track_type")], survey_exposure[, c("tornado_id", "ZCTA")] %>% mutate(s = TRUE), by = c("tornado_id", "ZCTA")); J$m <- !is.na(J$track_type); J$s <- !is.na(J$s); J$type <- tt$track_type[match(J$tornado_id, tt$tornado_id)]; J$line <- J$type == "line"
agr <- function(d) data.frame(tornadoes = length(unique(d$tornado_id)), spc_rows = sum(d$m), swath_rows = sum(d$s), both = sum(d$m & d$s), precision = mean(d$s[d$m]), recall = mean(d$m[d$s]), jaccard = sum(d$m & d$s) / sum(d$m | d$s))
R$d1_agreement <- rbind(all = agr(J), lines_only = agr(J[J$line, ]), point_tracks_only = agr(J[!J$line, ]))
# ---- (b) D2: widths of 0 ----------------------------------------------------------------------------------------------------------------------------------------
w0 <- which(tt$width_imputed & tt$track_type == "line"); R$d2 <- list(widths = table(type = ifelse(tt$track_type == "line", "line", "point"), imputed = tt$width_imputed), by_era = table(tt$track_type[tt$width_imputed], era[tt$width_imputed]), line_ratings = table(ifelse(is.na(tt$magnitude[w0]), "unknown", paste0("EF", tt$magnitude[w0]))), line_len_mi = quantile(tt$len_mi[w0], c(0, .5, .9, 1)))
cl <- st_transform(st_geometry(tornado_tracks)[w0], 5070); cz <- vector("list", length(w0))
for (v in c(2000, 2010, 2020)) { z <- Zfull(v); kk <- which(vint[w0] == v); h <- st_intersects(cl[kk], z); for (j in seq_along(kk)) cz[[kk[j]]] <- z$ZCTA[h[[j]]] }
pubz <- lapply(tt$tornado_id[w0], function(i) expo[[i]]); R$d2$lines <- length(w0); R$d2$published_rows <- sum(lengths(pubz)); R$d2$centerline_rows <- sum(lengths(cz)); R$d2$same_list <- sum(mapply(function(a, b) setequal(a, b), pubz, cz)); R$d2$centerline_subset_of_published <- sum(mapply(function(a, b) all(b %in% a), pubz, cz)); R$d2$no_zcta_by_centerline <- sum(lengths(cz) == 0)
R$d2$published_area_cols_rows <- sum(lengths(pubz)); lg("D2 done")
# ---- (d) D8: maps ---------------------------------------------------------------------------------------------------------------------------------------------------------
urls <- c(cb_2000 = "https://www2.census.gov/geo/tiger/PREVGENZ/zt/z500shp/zt99_d00_shp.zip", cb_2010 = "https://www2.census.gov/geo/tiger/GENZ2010/gz_2010_us_860_00_500k.zip", cb_2020 = "https://www2.census.gov/geo/tiger/GENZ2020/shp/cb_2020_us_zcta520_500k.zip",
  full_2000 = "https://www2.census.gov/geo/tiger/TIGER2010/ZCTA5/2000/tl_2010_us_zcta500.zip", full_2010 = "https://www2.census.gov/geo/tiger/TIGER2010/ZCTA5/2010/tl_2010_us_zcta510.zip", full_2020 = "https://www2.census.gov/geo/tiger/TIGER2020/ZCTA520/tl_2020_us_zcta520.zip")
R$d8_download <- do.call(rbind, lapply(names(urls), function(n) { f <- tempfile(fileext = ".zip"); t <- system.time(download.file(urls[[n]], f, mode = "wb", quiet = TRUE))[["elapsed"]]; u <- system.time(utils::unzip(f, exdir = tempfile()))[["elapsed"]]; r <- data.frame(file = n, zip_mb = file.size(f) / 1e6, download_s = t, unzip_s = u); unlink(f); lg("downloaded ", n, " ", round(r$zip_mb), " MB in ", round(t), " s"); r }))
cache <- rappdirs::user_cache_dir("tigris"); cmp <- function(ids, full_shp, cb_shp, cb_field, full_field, v) { sfull <- st_read(full_shp, query = sprintf("SELECT %s AS ZCTA FROM %s WHERE %s IN (%s)", full_field, tools::file_path_sans_ext(basename(full_shp)), full_field, paste0("'", ids, "'", collapse = ",")), quiet = TRUE)
  scb <- st_read(cb_shp, query = sprintf("SELECT %s AS ZCTA FROM %s WHERE %s IN (%s)", cb_field, tools::file_path_sans_ext(basename(cb_shp)), cb_field, paste0("'", ids, "'", collapse = ",")), quiet = TRUE); sfull <- st_make_valid(st_transform(sfull, 5070)); scb <- st_make_valid(st_transform(scb, 5070))
  nv <- function(g) vapply(st_geometry(g), function(x) sum(rapply(list(unclass(x)), function(m) nrow(m), classes = "matrix", how = "unlist")), 1)
  do.call(rbind, lapply(ids, function(z) { a <- sfull[sfull$ZCTA == z, ]; b <- scb[scb$ZCTA == z, ]; if (!nrow(a) || !nrow(b)) return(data.frame(ZCTA = z, found_full = nrow(a), found_cb = nrow(b))); ga <- st_geometry(a); gb <- st_geometry(b); un <- sum(as.numeric(st_area(st_union(ga, gb)))); sdv <- st_sym_difference(ga, gb); sd <- if (length(sdv) == 0) 0 else sum(as.numeric(st_area(sdv)))
    data.frame(ZCTA = z, found_full = 1, found_cb = 1, area_full_km2 = as.numeric(st_area(a)) / 1e6, area_cb_km2 = as.numeric(st_area(b)) / 1e6, area_ratio_cb_to_full = as.numeric(st_area(b)) / as.numeric(st_area(a)), sym_diff_share_of_union = sd / un, vertices_full = nv(a), vertices_cb = nv(b)) })) }
jz <- c("64801", "64804", "64840", "64841", "64844"); sl <- unique(tornado_exposure$ZCTA[tornado_exposure$tornado_id == "2025_2505161339-01"])
R$d8_joplin <- cmp(jz, file.path(cache, "tl_2010_us_zcta510.shp"), file.path(cache, "gz_2010_us_860_00_500k.shp"), "ZCTA5", "ZCTA5CE10", 2010); R$d8_stlouis <- cmp(sl, file.path(cache, "tl_2020_us_zcta520.shp"), file.path(cache, "cb_2020_us_zcta520_500k.shp"), "ZCTA5CE20", "ZCTA5CE20", 2020); lg("maps compared")
# ---- (e) sizes with no alteration ---------------------------------------------------------------------------------------------------------------------------------------
fx <- readRDS(qa_out("dat_full_fetch.rds")); R$e_fetch <- fx; L0 <- readRDS(qa_out("dat_full_layer0.rds")); L1 <- readRDS(qa_out("dat_full_layer1.rds")); L2 <- readRDS(qa_out("dat_full_layer2.rds"))
nv2 <- function(g) sum(vapply(st_geometry(g), function(x) sum(rapply(list(unclass(x)), function(m) nrow(m), classes = "matrix", how = "unlist")), 1)); R$e_vertices <- c(polygons = nv2(L2), lines = nv2(L1), points = nrow(L0), polygon_features = nrow(L2))
xz <- function(x, nm) { f <- tempfile(fileext = ".rda"); assign(nm, x); save(list = nm, file = f, compress = "xz"); s <- file.size(f) / 1e6; unlink(f); s }
sizes <- c(published_survey_tracks = file.size("data/survey_tracks.rda") / 1e6, published_data_folder = sum(file.size(list.files("data", full.names = TRUE))) / 1e6, dat_polygons_all_fields_xz = xz(L2, "x"), dat_lines_all_fields_xz = xz(L1, "x"), dat_points_all_fields_xz = xz(L0, "x"))
raw <- read.csv(qa_spc_csv(), stringsAsFactors = FALSE); sizes[["spc_complete_record_xz"]] <- xz(raw, "spc_full"); sizes[["spc_complete_record_csv"]] <- file.size(qa_spc_csv()) / 1e6; R$e_sizes_mb <- sizes; lg("sizes done")
Sfull <- readRDS(qa_out("pairing_R0_swaths_full.rds")); S4326 <- st_transform(Sfull, 4326); R$e_swaths_full_xz_mb <- xz(S4326[, "tornado_id"], "x"); R$e_swaths_n <- nrow(Sfull); R$e_swaths_vertices_full <- nv2(Sfull)
# the same swaths from polygons generalized by the service to 0.0002 degrees (the published fetch) and the published 50 m simplification
P20 <- readRDS(qa_out("dat_polys_live.rds")); Lp <- readRDS(qa_out("dat_lines_live.rds")); R$e_published_fetch <- c(polygons = nrow(P20), vertices = nv2(P20))
ex2 <- list(); ids <- Sfull$tornado_id; kk <- match(ids, tornado_tracks$tornado_id); Tt <- tornado_tracks[yr >= 2007, ]; Tt$date <- as.Date(Tt$date)
Lf <- L1; Lf$stormdate <- as.numeric(Lf$stormdate); Lf$length <- as.numeric(Lf$length); P20$stormdate <- as.numeric(P20$stormdate); dt <- function(x) as.POSIXct(as.numeric(x) / 1000, origin = "1970-01-01", tz = "UTC"); Lf$sd <- dt(Lf$stormdate); Lf <- Lf[!is.na(Lf$sd) & Lf$sd >= as.POSIXct("2007-01-01", tz = "UTC") & Lf$sd < as.POSIXct("2026-01-01", tz = "UTC") & !st_is_empty(Lf), ]; Du <- merge_copies(Lf); sv <- survey_paths(Du)
P20$sd <- NULL; sw20 <- swath_setup(Du, sv, P20); s20 <- vector("list", nrow(Sfull)); for (r in seq_len(nrow(Sfull))) { li <- match(as.integer(strsplit(Sfull$line_ids[r], ",")[[1]][1]), Du$objectid); k <- match(ids[r], Tt$tornado_id); s <- swath_of(sw20, li, k, Tt$wid_yd); s20[[r]] <- s$geom }
ok <- !vapply(s20, is.null, NA); R$e_swaths_found_with_20m_polygons <- sum(ok); g20 <- do.call(c, s20[ok]); st_crs(g20) <- 5070; a_full <- as.numeric(st_area(Sfull[ok, ])); a20 <- as.numeric(st_area(g20)); R$e_area_20m_vs_full_pct <- quantile(abs(a20 / a_full - 1) * 100, c(.5, .9, .99, 1))
g50 <- st_make_valid(st_simplify(g20, dTolerance = 50, preserveTopology = TRUE)); a50 <- as.numeric(st_area(g50)); R$e_area_50m_vs_full_pct <- quantile(abs(a50 / a_full - 1) * 100, c(.5, .9, .99, 1)); R$e_area_50m_vs_20m_pct <- quantile(abs(a50 / a20 - 1) * 100, c(.5, .9, .99, 1)); R$e_vertices_20m_swaths <- nv2(st_sf(geometry = g20)); R$e_vertices_50m_swaths <- nv2(st_sf(geometry = g50))
saveRDS(R, qa_out("decision_impact.rds")); lg("done 59"); for (nm in names(R)) { cat("\n##", nm, "\n"); print(R[[nm]]) }
